BEGIN;

INSERT INTO private.career_event_templates(event_key,source,title,body,choices) VALUES
('mate_training_tip','Companheiro','Um detalhe no seu movimento','Depois do treino, um companheiro comenta que percebeu um detalhe na forma como você recebe a bola e oferece uma sugestão.',
 '[{"key":"listen","label":"Ouvir e pedir para ele mostrar na prática.","effects":{"locker":2,"teammate_relation":5,"professionalism":1,"skills":{"tactical_awareness":2}},"result":"Você transformou o comentário em aprendizado.","reply_speaker":"Companheiro","reply":"Boa. Amanhã eu te mostro no campo. É coisa pequena, mas abre espaço quando você acerta o tempo."},{"key":"thank","label":"Agradecer, mas dizer que prefere trabalhar do seu jeito.","effects":{"teammate_relation":1,"morale":1,"ego":1},"result":"Você foi cordial sem mudar sua rotina.","reply_speaker":"Companheiro","reply":"Tranquilo. Cada um sente o jogo de um jeito. Só achei que podia ajudar."},{"key":"dismiss","label":"Dizer que não acha que isso seja um problema.","effects":{"teammate_relation":-3,"ego":2},"result":"O assunto morreu rápido e ficou um pequeno incômodo.","reply_speaker":"Companheiro","reply":"Beleza. Esquece então. Eu só estava tentando somar."}]'::jsonb),
('mate_extra_session_invite','Companheiro','Treino depois do treino','Um companheiro pergunta se você topa ficar mais alguns minutos depois da atividade para repetir jogadas específicas.',
 '[{"key":"join","label":"Aceitar e combinar uma sessão curta juntos.","effects":{"locker":2,"teammate_relation":6,"energy":-2,"fatigue":1,"skills":{"short_pass":2}},"result":"Vocês criaram uma pequena rotina de trabalho extra.","reply_speaker":"Companheiro","reply":"Fechado. Nada de exagerar. Uns minutos bem feitos valem mais do que ficar aqui até quebrar."},{"key":"later","label":"Dizer que hoje precisa recuperar, mas deixar para outro dia.","effects":{"teammate_relation":2,"discipline":1,"energy":1},"result":"Você preservou o corpo sem fechar a porta.","reply_speaker":"Companheiro","reply":"Justo. Me chama quando estiver inteiro e a gente faz."},{"key":"decline","label":"Recusar sem se comprometer com outra sessão.","effects":{"teammate_relation":-2,"personal":1},"result":"Ele entendeu, mas não insistiu mais.","reply_speaker":"Companheiro","reply":"Sem problema. Eu vou ficar um pouco mesmo assim."}]'::jsonb),
('mate_pass_complaint','Companheiro','“Eu estava livre.”','No fim da atividade, um companheiro comenta que você ignorou algumas opções de passe em jogadas em que ele aparecia livre.',
 '[{"key":"own","label":"Admitir que poderia ter levantado a cabeça mais cedo.","effects":{"locker":2,"teammate_relation":5,"ego":-1,"skills":{"tactical_awareness":2}},"result":"A conversa terminou com entendimento.","reply_speaker":"Companheiro","reply":"É só isso. Se eu estiver livre, confia. Eu também vou procurar você quando tiver espaço."},{"key":"explain","label":"Explicar o que você enxergou nas jogadas.","effects":{"teammate_relation":2,"professionalism":1},"result":"Vocês compararam leituras diferentes da mesma jogada.","reply_speaker":"Companheiro","reply":"Entendi seu lado. Então vamos ajustar o movimento para você ter as duas opções."},{"key":"pushback","label":"Responder que a decisão com a bola é sua.","effects":{"locker":-2,"teammate_relation":-6,"ego":3,"rivalry":1},"result":"O tom deixou a relação mais competitiva.","reply_speaker":"Companheiro","reply":"Beleza. Mas depois não reclama quando eu também escolher resolver sozinho."}]'::jsonb),
('mate_support_bad_week','Companheiro','Um apoio inesperado','Um jogador percebe que sua semana está pesada e pergunta se está tudo bem fora do campo.',
 '[{"key":"open","label":"Falar um pouco sobre a pressão que está sentindo.","effects":{"pressure":-4,"morale":3,"teammate_relation":6,"locker":2},"result":"A conversa tirou um pouco do peso da semana.","reply_speaker":"Companheiro","reply":"Todo mundo aqui passa por isso. Se precisar conversar, não precisa guardar tudo sozinho."},{"key":"light","label":"Dizer que está tudo sob controle e agradecer.","effects":{"pressure":-1,"teammate_relation":3},"result":"Você manteve a conversa leve.","reply_speaker":"Companheiro","reply":"Então beleza. Só quis ter certeza. Vamos nessa."},{"key":"close","label":"Evitar o assunto e dizer que prefere ficar sozinho.","effects":{"personal":2,"teammate_relation":-2,"locker":-1},"result":"Você preservou seu espaço, mas criou alguma distância.","reply_speaker":"Companheiro","reply":"Tranquilo. Respeito. Se mudar de ideia, sabe onde me achar."}]'::jsonb),
('mate_media_jealousy','Companheiro','Seu nome está aparecendo bastante','Um companheiro brinca que a imprensa parece interessada em tudo o que você faz e pergunta se você está gostando da atenção.',
 '[{"key":"team","label":"Dizer que prefere que falem do time, não só de você.","effects":{"locker":3,"teammate_relation":4,"ego":-2,"image":1},"result":"A resposta agradou quem teme que a exposição suba à cabeça.","reply_speaker":"Companheiro","reply":"Boa. Aqui ninguém ganha jogo sozinho. Se continuar assim, a galera vai comprar sua ideia."},{"key":"enjoy","label":"Admitir que gosta da exposição e quer aproveitar o momento.","effects":{"fame":1,"media":2,"teammate_relation":-1,"ego":2},"result":"Você não escondeu que gosta dos holofotes.","reply_speaker":"Companheiro","reply":"Justo. Só lembra que quando sobe rápido, a cobrança sobe junto."},{"key":"joke","label":"Brincar que ele está com ciúme das entrevistas.","effects":{"sociability":2,"teammate_relation":1,"locker":1},"result":"O clima virou piada.","reply_speaker":"Companheiro","reply":"Ciúme nada. Só quero meu microfone também quando eu fizer dois gols."}]'::jsonb),
('mate_social_invite','Companheiro','Convite depois do treino','Um companheiro chama você para sair com parte do elenco depois do expediente.',
 '[{"key":"go","label":"Aceitar o convite e combinar de ir com o grupo.","effects":{"locker":4,"teammate_relation":5,"morale":3,"energy":-2,"personal":2},"result":"Você se aproximou do grupo fora do ambiente de treino.","reply_speaker":"Companheiro","reply":"Boa. Sem loucura, só para relaxar um pouco. Vai ser bom você conhecer a galera fora daqui."},{"key":"short","label":"Dizer que aparece um pouco, mas vai embora cedo.","effects":{"locker":2,"teammate_relation":3,"discipline":1},"result":"Você conciliou integração e rotina.","reply_speaker":"Companheiro","reply":"Fechado. O importante é aparecer. Depois cada um cuida do próprio horário."},{"key":"no","label":"Recusar porque quer priorizar recuperação.","effects":{"discipline":2,"energy":2,"teammate_relation":-1},"result":"Você priorizou sua preparação.","reply_speaker":"Companheiro","reply":"Tá focado mesmo, hein? Tranquilo. Outra hora você cola."}]'::jsonb),
('mate_prank','Companheiro','Pegadinha no vestiário','Um companheiro tenta te colocar numa brincadeira do grupo para ver como você reage.',
 '[{"key":"play","label":"Entrar na brincadeira e devolver na mesma moeda.","effects":{"locker":4,"teammate_relation":4,"sociability":3,"morale":2},"result":"Você entrou no clima do grupo.","reply_speaker":"Companheiro","reply":"Agora sim. Achei que você ia ficar sério o tempo todo."},{"key":"smile","label":"Levar na esportiva, mas não prolongar.","effects":{"locker":2,"teammate_relation":2,"sociability":1},"result":"Você mostrou que sabe brincar sem perder o limite.","reply_speaker":"Companheiro","reply":"Tá bom, tá bom. Você passou no teste do vestiário."},{"key":"angry","label":"Cortar a brincadeira e dizer que não gostou.","effects":{"locker":-3,"teammate_relation":-4,"discipline":1},"result":"O clima esfriou imediatamente.","reply_speaker":"Companheiro","reply":"Calma. Era só brincadeira. Já entendi que com você não rola."}]'::jsonb),
('mate_tactical_disagreement','Companheiro','Leituras diferentes','Durante uma conversa tática, um companheiro discorda de onde você deveria se posicionar numa jogada recorrente.',
 '[{"key":"test","label":"Propor testar as duas ideias no próximo treino.","effects":{"locker":2,"teammate_relation":4,"professionalism":2,"skills":{"positioning":2}},"result":"A divergência virou experimento em campo.","reply_speaker":"Companheiro","reply":"Fechado. Se a sua funcionar melhor, eu admito. Se a minha funcionar, você me paga um café."},{"key":"coach","label":"Dizer que prefere seguir exatamente o que o treinador pediu.","effects":{"coach":2,"discipline":2,"teammate_relation":-1},"result":"Você priorizou a orientação da comissão.","reply_speaker":"Companheiro","reply":"Justo. Depois eu pergunto para ele como quer essa movimentação."},{"key":"insist","label":"Insistir que sua leitura é claramente melhor.","effects":{"teammate_relation":-5,"ego":2,"locker":-1},"result":"A discussão ficou mais pessoal do que tática.","reply_speaker":"Companheiro","reply":"Então mostra no treino. Falar que é melhor é fácil."}]'::jsonb),
('mate_penalty_talker','Companheiro','Quem bate se acontecer?','Um companheiro pergunta quem deveria assumir um pênalti importante se os dois estiverem em campo.',
 '[{"key":"claim","label":"Dizer que quer a responsabilidade se estiver confiante.","effects":{"ambition":2,"teammate_relation":-2,"pressure":2,"skills":{"penalties":1}},"result":"Você deixou claro que quer decisões grandes.","reply_speaker":"Companheiro","reply":"Gostei da coragem. Mas se eu estiver melhor no dia, vou querer também."},{"key":"merit","label":"Dizer que deve bater quem estiver melhor e for definido pela comissão.","effects":{"coach":2,"locker":2,"teammate_relation":3,"ego":-1},"result":"Você colocou a decisão acima da disputa pessoal.","reply_speaker":"Companheiro","reply":"Fechado. Sem ego. Quem estiver mais preparado assume."},{"key":"give","label":"Dizer que ele pode assumir e você prefere não entrar nessa disputa.","effects":{"pressure":-2,"teammate_relation":4,"ambition":-2},"result":"Você tirou uma disputa da mesa.","reply_speaker":"Companheiro","reply":"Valeu pela confiança. Mas se chegar sua hora, não foge dela."}]'::jsonb),
('mate_agent_rumor','Companheiro','“Estão falando que você pode sair.”','Um jogador pergunta diretamente sobre rumores de que seu empresário estaria conversando com outros clubes.',
 '[{"key":"deny","label":"Dizer que seu foco está totalmente no clube atual.","effects":{"locker":3,"teammate_relation":3,"fans":1,"agent":-1},"result":"Você tentou encerrar a especulação dentro do grupo.","reply_speaker":"Companheiro","reply":"Boa. Era só isso que eu queria ouvir. Rumor de fora entra fácil no vestiário."},{"key":"honest","label":"Dizer que escuta oportunidades, mas não decidiu nada.","effects":{"teammate_relation":1,"agent":2,"ambition":1,"locker":-1},"result":"A sinceridade manteve a conversa aberta, mas não matou o rumor.","reply_speaker":"Companheiro","reply":"Entendo. Só não deixa a gente descobrir tudo pela internet."},{"key":"private","label":"Dizer que sua carreira não é assunto do vestiário.","effects":{"teammate_relation":-4,"personal":2,"ego":1},"result":"Você protegeu sua privacidade e criou distância.","reply_speaker":"Companheiro","reply":"Beleza. Não pergunto mais. Só achei que valia falar de frente."}]'::jsonb),
('mate_cover_late','Companheiro','Ele pode te cobrir','Um companheiro percebe que você está atrasado para uma reunião interna e oferece uma desculpa para a comissão.',
 '[{"key":"accept","label":"Aceitar a cobertura e entrar sem chamar atenção.","effects":{"teammate_relation":5,"discipline":-3,"coach":-1},"result":"Você escapou da cobrança imediata, mas dependeu do companheiro.","reply_speaker":"Companheiro","reply":"Eu seguro essa. Mas não me faz virar seu álibi toda semana."},{"key":"own","label":"Recusar e assumir o atraso diretamente.","effects":{"coach":1,"discipline":3,"teammate_relation":2,"pressure":1},"result":"Você preferiu assumir a consequência.","reply_speaker":"Companheiro","reply":"Respeito. Melhor tomar a bronca agora do que criar história depois."},{"key":"blame","label":"Pedir para ele dizer que a comissão mudou o horário.","effects":{"teammate_relation":-5,"discipline":-4,"image":-1},"result":"O pedido deixou o companheiro desconfortável.","reply_speaker":"Companheiro","reply":"Aí não. Uma coisa é te dar cobertura, outra é inventar coisa colocando os outros no meio."}]'::jsonb),
('mate_mentor_advice','Companheiro','Conselho de quem já está aqui','Um dos jogadores mais estabelecidos no elenco chama você de lado e comenta sobre como sobreviver às semanas ruins.',
 '[{"key":"ask","label":"Perguntar o que mais pesa para um jovem dentro do clube.","effects":{"professionalism":2,"teammate_relation":5,"pressure":-2},"result":"Você recebeu um conselho mais profundo do que esperava.","reply_speaker":"Companheiro","reply":"Não é errar. É deixar um erro virar três dias ruins. Aprende a zerar rápido e volta para o próximo treino."},{"key":"confident","label":"Dizer que acredita conseguir lidar sozinho com a pressão.","effects":{"ambition":1,"morale":2,"teammate_relation":-1},"result":"Você demonstrou autoconfiança.","reply_speaker":"Companheiro","reply":"Tomara. Só não confunde confiança com achar que ninguém tem nada para ensinar."},{"key":"thank","label":"Agradecer e guardar o conselho sem prolongar a conversa.","effects":{"teammate_relation":3,"professionalism":1},"result":"A relação ganhou respeito sem grande exposição.","reply_speaker":"Companheiro","reply":"Tranquilo. Quando precisar, chega aí."}]'::jsonb),
('mate_ask_help','Companheiro','Ele quer sua ajuda','Um companheiro pede alguns minutos para você ajudá-lo a repetir uma situação em que ele está tendo dificuldade.',
 '[{"key":"help","label":"Ficar e ajudá-lo mesmo gastando parte do seu tempo livre.","effects":{"locker":4,"teammate_relation":7,"leadership":2,"energy":-2},"result":"Você investiu tempo na evolução de outro jogador.","reply_speaker":"Companheiro","reply":"Valeu mesmo. Quando você precisar repetir alguma coisa, me chama também."},{"key":"brief","label":"Ajudar rapidamente, mas manter seu plano do dia.","effects":{"locker":2,"teammate_relation":4,"professionalism":1},"result":"Você ajudou sem abandonar sua própria rotina.","reply_speaker":"Companheiro","reply":"Já clareou bastante. O resto eu continuo sozinho."},{"key":"no","label":"Dizer que precisa focar no seu próprio desenvolvimento.","effects":{"ambition":2,"teammate_relation":-3,"locker":-1},"result":"Você priorizou seu desenvolvimento individual.","reply_speaker":"Companheiro","reply":"Beleza. Eu resolvo. Só achei que você podia dar uma força."}]'::jsonb),
('mate_music_room','Companheiro','Quem manda na música?','Um companheiro entrega o celular e manda você escolher a música do vestiário antes do treino.',
 '[{"key":"takeover","label":"Assumir a playlist e colocar o que você gosta.","effects":{"sociability":3,"locker":2,"teammate_relation":2,"ego":1},"result":"Você deixou um pouco mais da sua personalidade no ambiente.","reply_speaker":"Companheiro","reply":"Tá aprovado... por enquanto. Se a gente perder, a culpa da playlist é sua."},{"key":"group","label":"Perguntar o que o grupo quer ouvir e montar junto.","effects":{"locker":4,"teammate_relation":3,"leadership":1},"result":"A escolha virou um pequeno momento coletivo.","reply_speaker":"Companheiro","reply":"Aí sim. Democracia até alguém colocar uma música horrível."},{"key":"pass","label":"Devolver o celular e dizer que não liga para isso.","effects":{"teammate_relation":0,"sociability":-1},"result":"Você ficou fora da brincadeira.","reply_speaker":"Companheiro","reply":"Você é difícil, hein? Então deixa que eu resolvo."}]'::jsonb),
('mate_social_post','Companheiro','Foto do elenco','Um companheiro quer postar uma foto de vocês depois do treino e pergunta se pode marcar seu perfil.',
 '[{"key":"yes","label":"Deixar postar e entrar na brincadeira nos comentários.","effects":{"locker":2,"teammate_relation":3,"media":1,"image":1,"fame":1,"fanbase":8},"result":"A publicação aproximou sua imagem do grupo.","reply_speaker":"Companheiro","reply":"Boa. Já vou postar antes que você mude de ideia."},{"key":"photo_only","label":"Deixar postar, mas pedir para não marcar seu perfil.","effects":{"teammate_relation":1,"personal":2},"result":"Você preservou parte da privacidade sem criar conflito.","reply_speaker":"Companheiro","reply":"Fechado. Foto vai, marcação não."},{"key":"no","label":"Pedir para não publicar a foto.","effects":{"personal":3,"teammate_relation":-2,"locker":-1},"result":"O companheiro respeitou, embora tenha achado estranho.","reply_speaker":"Companheiro","reply":"Tá bom. Eu corto você da foto. Sem problema."}]'::jsonb),
('mate_captain_standard','Capitão','O padrão do grupo','O capitão comenta que algumas atitudes pequenas no dia a dia definem quem o elenco passa a confiar quando a pressão aumenta.',
 '[{"key":"ask","label":"Perguntar o que ele espera de você especificamente.","effects":{"locker":3,"teammate_relation":4,"leadership":1,"professionalism":2},"result":"Você recebeu uma cobrança direta e útil.","reply_speaker":"Capitão","reply":"Pontualidade, treino sério e não sumir quando a fase aperta. O resto a gente constrói."},{"key":"prove","label":"Dizer que prefere provar no dia a dia do que falar.","effects":{"locker":1,"ambition":2,"teammate_relation":1},"result":"Você respondeu com postura competitiva.","reply_speaker":"Capitão","reply":"Perfeito. Então faz. Aqui ninguém precisa de discurso bonito."},{"key":"relax","label":"Dizer que o ambiente também precisa ser leve, não só cobrança.","effects":{"sociability":2,"locker":1,"teammate_relation":-1},"result":"Você trouxe outra visão para a conversa.","reply_speaker":"Capitão","reply":"Concordo. Leveza é boa. Só não pode virar relaxo quando começa a valer ponto."}]'::jsonb),
('mate_rival_challenge','Rival','“A vaga não é sua.”','O jogador que disputa posição com você diz, sem rodeios, que não pretende aceitar ficar atrás na hierarquia.',
 '[{"key":"respect","label":"Dizer que quer uma disputa forte e limpa.","effects":{"teammate_relation":3,"locker":1,"rivalry":-1,"ambition":1},"result":"A rivalidade ganhou respeito competitivo.","reply_speaker":"Rival","reply":"Então estamos entendidos. Quem estiver melhor joga. Sem desculpa."},{"key":"fire","label":"Responder que ele vai precisar correr muito para tirar sua vaga.","effects":{"teammate_relation":-7,"rivalry":1,"ego":2,"ambition":2},"result":"Você elevou a temperatura da disputa.","reply_speaker":"Rival","reply":"É disso que eu gosto. Guarda essa frase para depois do próximo treino."},{"key":"ignore","label":"Não alimentar a provocação.","effects":{"pressure":-1,"teammate_relation":-1},"result":"Você não entrou no confronto.","reply_speaker":"Rival","reply":"Silêncio também responde. A gente vê no campo."}]'::jsonb),
('mate_rival_respect','Rival','Respeito depois de uma disputa','Depois de uma sessão muito competitiva, seu rival reconhece que você elevou o nível do treino.',
 '[{"key":"return","label":"Reconhecer que ele também te força a melhorar.","effects":{"teammate_relation":6,"rivalry":-1,"locker":2,"professionalism":1},"result":"A rivalidade ficou mais saudável.","reply_speaker":"Rival","reply":"É isso. Eu quero sua vaga, mas prefiro ganhar de alguém que me faça melhorar."},{"key":"cold","label":"Agradecer de forma curta e seguir.","effects":{"teammate_relation":1,"rivalry":0},"result":"O respeito ficou implícito, sem aproximação.","reply_speaker":"Rival","reply":"Tá. Amanhã tem mais."},{"key":"taunt","label":"Dizer que ele só percebeu agora porque você está abrindo vantagem.","effects":{"teammate_relation":-5,"rivalry":1,"ego":2},"result":"O elogio virou nova provocação.","reply_speaker":"Rival","reply":"Não se empolga. Uma semana boa não ganha temporada."}]'::jsonb),
('mate_rival_contact','Rival','Dividida mais forte','Seu concorrente chega mais firme numa dividida e depois pergunta se você achou que ele passou do ponto.',
 '[{"key":"clean","label":"Dizer que faz parte da disputa e seguir treinando.","effects":{"teammate_relation":3,"rivalry":-1,"morale":1},"result":"Você tirou peso do lance.","reply_speaker":"Rival","reply":"Boa. Eu também não quero fazer ninguém se machucar. Só não vou aliviar."},{"key":"warn","label":"Avisar que intensidade não dá direito de colocar alguém em risco.","effects":{"teammate_relation":0,"locker":1,"discipline":2},"result":"Você colocou um limite sem recuar da disputa.","reply_speaker":"Rival","reply":"Justo. Se eu passar do ponto de novo, fala na hora."},{"key":"retaliate","label":"Dizer que na próxima dividida ele vai receber igual.","effects":{"teammate_relation":-8,"rivalry":1,"locker":-2,"discipline":-2},"result":"A tensão virou ameaça de revanche.","reply_speaker":"Rival","reply":"Então vamos ver quem recua primeiro."}]'::jsonb),
('mate_rival_media','Rival','Comparação na imprensa','Uma matéria comparou você diretamente com o jogador que disputa sua posição. Ele toca no assunto no vestiário.',
 '[{"key":"reject","label":"Dizer que a comparação de fora não muda a relação dentro do time.","effects":{"locker":3,"teammate_relation":4,"media":-1,"rivalry":-1},"result":"Você separou competição interna de narrativa externa.","reply_speaker":"Rival","reply":"Melhor assim. A imprensa precisa de história; a gente precisa jogar."},{"key":"embrace","label":"Dizer que a comparação é justa e que você quer mostrar que é melhor.","effects":{"fame":1,"media":2,"teammate_relation":-6,"rivalry":1,"ambition":2},"result":"Você abraçou publicamente a disputa.","reply_speaker":"Rival","reply":"Perfeito. Então não reclama quando eu responder do mesmo jeito."},{"key":"joke","label":"Brincar que pelo menos colocaram uma foto boa dos dois.","effects":{"sociability":2,"teammate_relation":2,"pressure":-1},"result":"A piada tirou parte do peso da comparação.","reply_speaker":"Rival","reply":"A sua estava melhor mesmo. No campo eu compenso."}]'::jsonb),
('mate_goal_drought_support','Companheiro','“O gol vai sair.”','Um atacante do elenco comenta que percebeu sua ansiedade para produzir números e diz que isso pode estar atrapalhando.',
 '[{"key":"listen","label":"Perguntar como ele lida com períodos sem gol ou assistência.","effects":{"pressure":-3,"teammate_relation":5,"professionalism":1,"skills":{"finishing_touch":1}},"result":"A conversa ajudou a colocar a fase em perspectiva.","reply_speaker":"Companheiro","reply":"Eu tento voltar para a jogada certa. Quando começo a caçar gol, normalmente jogo pior."},{"key":"confidence","label":"Dizer que não está preocupado e que os números vão aparecer.","effects":{"morale":2,"pressure":-1,"teammate_relation":1},"result":"Você reforçou confiança no próprio processo.","reply_speaker":"Companheiro","reply":"Então mantém. Eu só não queria ver você se cobrando por coisa que ainda vai acontecer."},{"key":"irritated","label":"Dizer que não precisa de conselho sobre seus números.","effects":{"teammate_relation":-4,"pressure":1,"ego":2},"result":"A tentativa de apoio terminou mal.","reply_speaker":"Companheiro","reply":"Beleza. Não falo mais. Boa sorte então."}]'::jsonb),
('mate_defensive_effort','Companheiro','Cobrança sem a bola','Um companheiro diz que, quando você perde a bola, espera que você ajude mais na recomposição.',
 '[{"key":"accept","label":"Aceitar a cobrança e perguntar onde ele precisa de cobertura.","effects":{"locker":3,"teammate_relation":5,"coach":1,"skills":{"positioning":2}},"result":"A cobrança virou alinhamento coletivo.","reply_speaker":"Companheiro","reply":"É só fechar por dentro primeiro. Se fizer isso, eu consigo sair na pressão sem deixar buraco."},{"key":"role","label":"Dizer que seu papel principal é criar e atacar.","effects":{"teammate_relation":-3,"ego":2,"locker":-1},"result":"Você defendeu uma visão mais individual da função.","reply_speaker":"Companheiro","reply":"Todo mundo tem função principal. Mas quando perde a bola, a gente defende com onze."},{"key":"coach","label":"Dizer que vai confirmar com o treinador exatamente o que ele quer.","effects":{"coach":2,"teammate_relation":1,"professionalism":2},"result":"Você levou a discussão para um critério objetivo.","reply_speaker":"Companheiro","reply":"Perfeito. Se ele disser que é diferente, eu ajusto também."}]'::jsonb),
('mate_private_confidence','Companheiro','Uma conversa mais pessoal','Um companheiro admite que está inseguro com a própria posição no elenco e pergunta se você já passou por algo parecido.',
