CREATE OR REPLACE FUNCTION private.pick_teammate_dialogue_event(p_player_id uuid,p_teammate_id uuid,p_activity_key text)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=''
AS $$
DECLARE
  v_relation int:=50; v_rival boolean:=false; v_same_position boolean:=false; v_form int:=50; v_pressure int:=25;
  v_candidates text[]; v_recent text[]; v_available text[]; v_key text;
BEGIN
  SELECT coalesce(r.relation,50),coalesce(r.rivalry,false),(ai.primary_position=j.posicao),coalesce(pcs.form,50),coalesce(pcs.pressure,25)
  INTO v_relation,v_rival,v_same_position,v_form,v_pressure
  FROM public.player_teammate_relations r
  JOIN public.base_ai_players ai ON ai.id=r.teammate_id
  JOIN public.jogadores j ON j.id=r.player_id
  JOIN public.player_career_state pcs ON pcs.player_id=r.player_id
  WHERE r.player_id=p_player_id AND r.teammate_id=p_teammate_id;

  IF v_rival OR v_relation<=34 THEN
    v_candidates:=ARRAY['mate_rival_challenge','mate_rival_respect','mate_rival_contact','mate_rival_media','mate_pass_complaint','mate_defensive_effort'];
  ELSIF v_same_position THEN
    v_candidates:=ARRAY['mate_rival_challenge','mate_penalty_talker','mate_tactical_disagreement','mate_training_tip','mate_extra_session_invite','mate_media_jealousy'];
  ELSIF v_pressure>=55 OR v_form<=42 THEN
    v_candidates:=ARRAY['mate_support_bad_week','mate_goal_drought_support','mate_private_confidence','mate_mentor_advice','mate_recovery_warning','mate_first_big_game'];
  ELSIF p_activity_key IN ('team_training_intense','team_training_normal','team_training_light','teammate_extra','watch_match_analysis') THEN
    v_candidates:=ARRAY['mate_training_tip','mate_extra_session_invite','mate_tactical_disagreement','mate_defensive_effort','mate_recovery_warning','mate_routine_question','mate_ask_help'];
  ELSIF v_relation>=70 THEN
    v_candidates:=ARRAY['mate_social_invite','mate_prank','mate_social_post','mate_private_confidence','mate_ask_help','mate_music_room','mate_contract_money'];
  ELSE
    v_candidates:=ARRAY['mate_training_tip','mate_social_invite','mate_prank','mate_media_jealousy','mate_agent_rumor','mate_mentor_advice','mate_ask_help','mate_music_room','mate_social_post','mate_captain_standard','mate_leadership_test','mate_routine_question','mate_contract_money','mate_first_big_game'];
  END IF;

  SELECT coalesce(array_agg(event_key),'{}'::text[]) INTO v_recent
  FROM (
    SELECT event_key FROM public.player_career_events
    WHERE player_id=p_player_id AND status='resolved'
    ORDER BY created_at DESC LIMIT 6
  ) x;

  SELECT coalesce(array_agg(c),'{}'::text[]) INTO v_available
  FROM unnest(v_candidates)c
  WHERE NOT (c=ANY(v_recent));
  IF cardinality(v_available)=0 THEN v_available:=v_candidates; END IF;
  v_key:=v_available[1+floor(random()*cardinality(v_available))::int];
  RETURN v_key;
END;
$$;

-- O motor existente ainda decide QUANDO uma conversa deve acontecer. Este trigger
-- apenas troca os dois diálogos genéricos por um diálogo contextual, depois do sorteio.
CREATE OR REPLACE FUNCTION private.rewrite_generic_teammate_dialogue()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=''
AS $$
DECLARE
  v_event record; v_teammate uuid; v_key text; v_template record; v_name text;
BEGIN
  SELECT e.* INTO v_event
  FROM public.player_career_events e
  WHERE e.player_id=NEW.player_id AND e.status='pending'
    AND e.event_key IN ('teammate_locker_room','rival_training_tension')
    AND e.metadata->>'kind'='teammate_interaction'
  ORDER BY e.created_at DESC LIMIT 1;
  IF v_event.id IS NULL THEN RETURN NEW; END IF;

  v_teammate:=nullif(v_event.metadata->>'teammate_id','')::uuid;
  IF v_teammate IS NULL THEN RETURN NEW; END IF;
  v_key:=private.pick_teammate_dialogue_event(NEW.player_id,v_teammate,NEW.activity_key);
  SELECT * INTO v_template FROM private.career_event_templates WHERE event_key=v_key;
  SELECT name INTO v_name FROM public.base_ai_players WHERE id=v_teammate;
  IF v_template.event_key IS NULL THEN RETURN NEW; END IF;

  UPDATE public.player_career_events
  SET event_key=v_key,
      source=coalesce(v_name,v_template.source),
      title=v_template.title,
      body=v_template.body,
      metadata=metadata||jsonb_build_object('dialogue_engine','v2','activity',NEW.activity_key)
  WHERE id=v_event.id;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_after_career_action_zz_teammate_dialogue ON public.player_career_actions;
CREATE TRIGGER trg_after_career_action_zz_teammate_dialogue
AFTER INSERT ON public.player_career_actions
FOR EACH ROW EXECUTE FUNCTION private.rewrite_generic_teammate_dialogue();

COMMIT;
